import * as React from 'react';

import { IconButton } from '../../actions/IconButton/IconButton.tsx';

import cl from './Tag.module.scss';


export { cl as TagClassNames };

export type TagProps = Omit<ComponentProps<'div'>, 'content' | 'children'> & {
