     4→
     5→import { assertUnreachable } from '../../../util/types.ts';
     6→
     7→import * as React from 'react';
     8→import { classNames as cx, type ComponentProps } from '../../../util/componentUtil.ts';
     9→
    10→import { type IconName, type IconProps, Icon } from '../../graphics/Icon/Icon.tsx';
    11→import { Button } from '../../actions/Button/Button.tsx';
    12→import { TooltipProvider } from '../../overlays/Tooltip/TooltipProvider.tsx';
    13→
    14→import cl from './Banner.module.scss';
    15→import { IconButton } from '../../actions/IconButton/IconButton.tsx';
    16→
    17→
    18→export { cl as BannerClassNames };
    19→
    20→export type BannerVariant = 'info' | 'warning' | 'error' | 'success';
    21→
    22→type BannerVariantIconProps = Omit<IconProps, 'icon'> & {
    23→  icon?: IconProps['icon'], // Make optional
    24→  variant: BannerVariant,
    25→};
    26→const BannerVariantIcon = ({ variant, ...propsRest }: BannerVariantIconProps) => {
    27→  const icon = ((): IconName => {
    28→    switch (variant) {
    29→      case 'info': return 'info-filled';
    30→      case 'warning': return 'warning-filled';
    31→      case 'error': return 'status-failed-filled';
    32→      case 'success': return 'status-success-filled';
    33→      default: return assertUnreachable(variant);
    34→    }
    35→  })();
    36→  return <Icon icon={icon} {...propsRest}/>;
    37→};
    38→
    39→
    40→type ActionButtonProps = ComponentProps<typeof Button>;
    41→/**
    42→ * A customized version of the `<Button/>` component specifically meant to be used for banner actions.
    43→ */
    44→const ActionButton = (props: ActionButtonProps) => {
    45→  return (
    46→    <Button trimmed
    47→      {...props}
    48→      className={cx(cl['bk-banner__action'], cl['bk-banner__action--button'], props.className)}
    49→      // Prevent clicks from triggering any click handlers on the Banner itself (e.g. to prevent toast dismissal)
    50→      onClick={event => { event.stopPropagation(); props.onClick?.(event); }}
    51→    />
    52→  );
    53→};
    54→
    55→type ActionIconProps = ComponentProps<typeof IconButton> & {
    56→  /** Optional custom tooltip text, if different from `label`. */
    57→  tooltip?: undefined | ComponentProps<typeof TooltipProvider>['tooltip'],
    58→};
    59→/**
    60→ * An action that is rendered as just an icon.
    61→ */
    62→const ActionIcon = ({ tooltip, ...buttonProps }: ActionIconProps) => {
    63→  return (
    64→    <TooltipProvider compact tooltip={typeof tooltip !== 'undefined' ? tooltip : buttonProps.label}>
    65→      <IconButton
    66→        {...buttonProps}
    67→        className={cx(cl['bk-banner__action'], cl['bk-banner__action--icon'], buttonProps.className)}
    68→        // Prevent clicks from triggering any click handlers on the Banner itself (e.g. to prevent toast dismissal)
    69→        onClick={event => { event.stopPropagation(); buttonProps.onClick?.(event); }}
    70→      />
    71→    </TooltipProvider>
    72→  );
    73→};
    74→
    75→
    76→export type BannerProps = Omit<ComponentProps<'div'>, 'title'> & {
    77→  /** Whether this component should be unstyled. */
    78→  unstyled?: undefined | boolean,
    79→  
    80→  /** Whether to trim this component (strip any spacing around the element). */
    81→  trimmed?: undefined | boolean,
    82→  
    83→  /** Whether to attempt to display the banner as a single line. */
    84→  compact?: undefined | boolean,
    85→  
    86→  /** Which variant to display, which changes the color and left icon. Defaults to "info". */
    87→  variant?: undefined | BannerVariant,
    88→  
    89→  /** The title of the banner. Optional. */
    90→  title?: undefined | React.ReactNode,
    91→  
    92→  /** If specified, a close action is displayed. Default: false. */
    93→  showCloseAction?: undefined | boolean,
    94→  
    95→  /** Callback that is called when the user requests the banner to close. */
    96→  onClose?: undefined | (() => void),
    97→  
    98→  /** Any additional actions to be shown in the banner. */
    99→  actions?: undefined | React.ReactNode,
   100→};
   101→/**
   102→ * An inline banner that displays a message to the user, usually of a time-sensitive nature.
   103→ */
   104→export const Banner = Object.assign(
   105→  (props: BannerProps) => {
   106→    const {
   107→      unstyled = false,
   108→      trimmed = false,
   109→      compact = true,
   110→      variant = 'info',
   111→      title = '',
   112→      showCloseAction = false,
   113→      onClose,
   114→      actions = null,
   115→      children,
   116→      ...propsRest
   117→    } = props;
   118→    
   119→    if (showCloseAction && typeof onClose !== 'function') {
   120→      console.error(`Missing prop in <Banner/>: 'onClose' function`);
   121→    }
   122→    
   123→    const renderTitle = () => {
   124→      if (title) { return title; }
   125→      
   126→      switch (variant) {
   127→        case 'info': return 'Info';
   128→        case 'warning': return 'Warning';
   129→        case 'error': return 'Error';
   130→        case 'success': return 'Success';
   131→        default: return assertUnreachable(variant);
   132→      }
   133→    };
   134→    
