     7→import { mergeRefs, mergeCallbacks } from '../../../../util/reactUtil.ts';
     8→import * as InputUtil from '../../../util/input_util.tsx';
     9→
    10→import { type IconName, Icon as IconDefault } from '../../../graphics/Icon/Icon.tsx';
    11→import { IconButton } from '../../../actions/IconButton/IconButton.tsx';
    12→
    13→import cl from './Input.module.scss';
    14→
    15→
    16→export { cl as InputClassNames };
    17→
    18→export type InputIconProps = Omit<ComponentProps<typeof IconDefault>, 'icon'> & {
    19→  icon?: undefined | string, // Loosen `icon` constraint (for custom `Icon` components)
    20→};
    21→
    22→const InputAction = (props: React.ComponentProps<typeof IconButton>) => {
    23→  const preventDefault = React.useCallback((event: React.MouseEvent) => {
    24→    event.preventDefault();
    25→  }, []);
    26→  
    27→  return (
    28→    <IconButton
    29→      {...props}
    30→      className={cx('action-icon', props.className)}
    31→      // Prevent cursor shifting when clicking on actions (see also: https://github.com/mui/material-ui/issues/26007)
    32→      onMouseDown={preventDefault}
    33→      onMouseUp={preventDefault}
    34→    />
    35→  );
    36→};
    37→
    38→type InputSpecificProps = Omit<InputUtil.InputSpecificProps, 'type'>;
    39→type InputContainerProps = Omit<ComponentProps<'div'>, 'ref' | 'prefix' | keyof InputSpecificProps>;
    40→export type InputProps = InputContainerProps & InputSpecificProps & {
    41→  /**
    42→   * By default, the `ref` will be linked to the inner input element. To get a ref to the container, use
    43→   * `containerProps.ref`.
    44→   */
    45→  ref?: undefined | React.Ref<HTMLInputElement>,
    46→  
    47→  /** Whether this component should be unstyled. */
    48→  unstyled?: undefined | boolean,
    49→  
    50→  /** The type of the input. */
    51→  type?: undefined | Exclude<ComponentProps<'input'>['type'], 'button' | 'submit' | 'reset'>,
    52→  
    53→  /** Props to apply to the container element. */
    54→  containerProps?: React.ComponentProps<'span'>,
    55→  
    56→  /** Props to apply to the inner `<input/>` element. */
    57→  inputProps?: React.ComponentProps<'input'>,
    58→  
    59→  /** A custom `Icon` component. */
    60→  Icon?: undefined | React.ComponentType<InputIconProps>,
    61→  
    62→  /** An icon to show before the input. */
    63→  icon?: undefined | IconName,
    64→  
    65→  /** The accessible name for the icon. */
    66→  iconLabel?: undefined | string,
    67→  
    68→  /** Additional props to pass to the `Icon`. */
    69→  iconProps?: undefined | Partial<InputIconProps>,
    70→  
    71→  /** Some prefilled content to be shown before the user input. */
    72→  prefix?: undefined | React.ReactNode,
    73→  
    74→  /** Any additional actions to show after the input control. Use `<Input.Action/>` for a preset action element. */
    75→  actions?: undefined | React.ReactNode,
    76→  
    77→  /**
    78→   * Whether the textarea should resize automatically, with `field-sizing: content`.
    79→   * Note that browser support is still somewhat limited:
    80→   * https://developer.mozilla.org/en-US/docs/Web/CSS/field-sizing
    81→   */
    82→  automaticResize?: undefined | boolean,
    83→};
    84→/**
    85→ * A text input control.
    86→ */
    87→export const Input = Object.assign(
    88→  (props: InputProps) => {
    89→    const {
    90→      id,
    91→      className,
    92→      ref,
    93→      unstyled = false,
    94→      type = 'text',
    95→      containerProps = {},
    96→      inputProps = {},
    97→      Icon = (IconDefault as React.ComponentType<InputIconProps>),
    98→      icon,
    99→      iconLabel,
   100→      iconProps = {},
   101→      prefix,
   102→      actions,
   103→      automaticResize,
   104→      ...propsRest
   105→    } = props;
   106→    
   107→    // Split props into container-specific and input-specific
   108→    const propsExtracted = InputUtil.extractInputSpecificProps(propsRest);
   109→    
   110→    const inputRef = React.useRef<HTMLInputElement>(null);
   111→    
   112→    // When the user clicks on the container, focus the input
   113→    const handleContainerClick = React.useCallback((event: React.MouseEvent) => {
   114→      // Note: make sure to exclude the input element itself, otherwise the user cannot click to move the cursor
   115→      if (event.target !== inputRef.current) {
   116→        event.preventDefault(); // Prevent the browser unfocusing the input right after this event is handled
   117→        inputRef.current?.focus();
   118→      }
   119→    }, []);
   120→    
   121→    // Prevent inputs from being used as (form submit) buttons
   122→    const bannedTypes = ['button', 'submit', 'image', 'reset'];
   123→    if (bannedTypes.includes(type)) {
   124→      throw new Error(`Input: unsupported type '${type}'.`);
   125→    }
   126→    if (inputProps.type && bannedTypes.includes(inputProps.type)) {
   127→      throw new Error(`Input: unsupported type '${type}'.`);
   128→    }
   129→    
   130→    // Note: this could be done with TypeScript, but Storybook types break when encountering `& ({ ... } | { ... })`
   131→    if (icon && !iconLabel) {
   132→      throw new Error(`When you specify an 'icon' on 'Input', you must also specify the 'iconLabel'.`);
   133→    }
   134→    
   135→    return (
   136→      // biome-ignore lint/a11y/noStaticElementInteractions: Visual-only convenience.
   137→      <span
   138→        {...containerProps}
   139→        {...propsExtracted.containerProps}
   140→        className={cx(
   141→          'bk',
   142→          { [cl['bk-input']]: !unstyled },
   143→          { [cl['bk-input--automatic-resize']]: automaticResize },
   144→          containerProps.className,
   145→          className,
   146→        )}
   147→        onMouseDown={mergeCallbacks(
   148→          [handleContainerClick, containerProps.onMouseDown, propsExtracted.containerProps.onMouseDown]
   149→        )}
   150→      >
   151→        {(icon || Icon !== IconDefault) &&
   152→          <Icon icon={icon} aria-label={iconLabel} {...iconProps} className={cx('input-icon', iconProps.className)}/>
   153→        }
   154→        {prefix}
   155→        <input
   156→          id={id}
   157→          {...inputProps}
   158→          {...propsExtracted.inputProps}
   159→          ref={mergeRefs(inputRef, inputProps?.ref, ref)}
   160→          type={type}
   161→          className={cx(cl['bk-input__input'], inputProps?.className)}
   162→        />
   163→        {actions}
   164→      </span>
   165→    );
   166→  },
   167→  {
   168→    Action: InputAction,
   169→  },
   170→);
