    14→// Represents a stack of modal dialog elements that are currently open in the top layer
    15→export type ModalDialogStack = ReadonlyArray<ModalDialogRef>;
    16→
    17→export type ModalDialogStackSubscriber = (this: ModalDialogStackObservable, modalDialogStack: ModalDialogStack) => void;
    18→/** Observable for a `ModalDialogStack`, can be subscribed to to listen for updates. */
    19→export class ModalDialogStackObservable {
    20→  #subscribers: Set<ModalDialogStackSubscriber> = new Set();
    21→  #modalDialogStack: ModalDialogStack = [];
    22→  
    23→  /** Subscribe to updates. Returns a function to unsubscribe. */
    24→  subscribe(subscriber: ModalDialogStackSubscriber): () => void {
    25→    this.#subscribers.add(subscriber);
    26→    subscriber.call(this, this.#modalDialogStack); // Publish the current state
    27→    return () => { this.#subscribers.delete(subscriber); };
    28→  }
    29→  
    30→  /** Publish the current state to all subscribers. */
    31→  publish() {
    32→    for (const subscriber of this.#subscribers) {
    33→      subscriber.call(this, this.#modalDialogStack);
    34→    }
    35→  }
