    46→    // move to the top of the stack.
    47→    this.#modalDialogStack = [...this.#modalDialogStack.filter(ref => ref.id !== modalDialog.id), modalDialog];
    48→    this.publish();
    49→  }
    50→  deactivate(modalDialog: ModalDialogRef) {
    51→    this.#modalDialogStack = [...this.#modalDialogStack.filter(ref => ref.id !== modalDialog.id)];
    52→    this.publish();
    53→  }
    54→}
